import React, { useState } from 'react';
import { Sparkles, ChevronRight, CheckCircle2, X } from 'lucide-react';

const initialFaq = [
  {
    id: 1,
    question: 'Do you offer delivery?',
    answer: 'Currently, we focus on dine-in experiences, but we are exploring delivery options for our most loyal customers.',
    isOpen: false,
  },
  {
    id: 2,
    question: 'What types of wine do you serve?',
    answer: 'We pride ourselves on a curated selection of natural and organic wines from small producers across Italy and the Mediterranean.',
    isOpen: false,
  },
  {
    id: 3,
    question: 'Can I bring my own bottle?',
    answer: 'Yes, we welcome guests to bring their own bottle for corkage. Please inform us ahead of your reservation.',
    isOpen: false,
  },
  {
    id: 4,
    question: 'Do you accommodate dietary restrictions?',
    answer: 'Absolutely! We work with many guests with special dietary needs. Please let us know in advance so we can tailor the menu.',
    isOpen: false,
  },
  {
    id: 5,
    question: 'What time is last call?',
    answer: 'Last call is at 10:00 PM. We aim to create a cozy atmosphere that extends into the evening, but we respect all our guests.',
    isOpen: false,
  },
];

export default function Faq() {
  const [currentFaq, setCurrentFaq] = useState(initialFaq);

  const toggleAccordion = (id) => {
    setCurrentFaq((prev) =>
      prev.map((faq) => {
        if (faq.id === id) {
          return { ...faq, isOpen: !faq.isOpen };
        }
        return faq;
      })
    );
  };

  return (
    <div className="w-full max-w-6xl mx-auto p-6 sm:p-10 bg-slate-950 text-slate-100">
      <div className="mb-12 text-center">
        <h2 className="text-2xl sm:text-3xl font-bold tracking-tight text-amber-400">
          Frequently Asked Questions
        </h2>
        <p className="mt-4 text-slate-400 max-w-md mx-auto">
          Here are some common questions and answers to help you plan your visit.
        </p>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
        {currentFaq.map((faq) => (
          <div
            key={faq.id}
            className="group relative rounded-2xl bg-white/5 backdrop-blur-xl border border-white/10 p-6 transition-all duration-300 hover:scale-[1.02] hover:shadow-2xl hover:shadow-amber/30"
          >
            <div className="absolute -inset-0.5 bg-white/5 rounded-2xl border border-white/10" />
            <div className="flex justify-between items-start mb-6">
              <div className="flex items-center gap-3 text-slate-400">
                <Sparkles className="w-5 h-5 text-amber-400" />
                {faq.question}
              </div>
              <button
                onClick={() => toggleAccordion(faq.id)}
                className="p-2 rounded-lg text-slate-500 hover:text-white transition-colors"
              >
                <ChevronRight className="w-5 h-5" />
              </button>
            </div>
            {faq.isOpen && (
              <div className="text-slate-400 max-w-md">
                <p className="mt-4">{faq.answer}</p>
                <div className="flex items-center justify-between mt-6">
                  <div className="flex items-center gap-2">
                    <CheckCircle2 className="w-5 h-5 text-emerald-400" />
                    <span>Got it!</span>
                  </div>
                  <button
                    onClick={() => toggleAccordion(faq.id)}
                    className="text-slate-500 hover:text-white transition-colors"
                  >
                    <X className="w-5 h-5" />
                  </button>
                </div>
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

